for (const row of snapshot.experiments) {
  const route = `/live/experiments/${row.id}/`;
  meta[route] = { title: `${row.title} | LARI Experiments`, description: `${row.summary} Evidence status: ${row.verificationStatus}.`, image: `/assets/social-cards/experiment-${row.id}.png`, imageAlt: `LARI experiment: ${row.title}. Approved research record with evidence status ${row.verificationStatus}.`, lastModified: row.publishedAt || row.measuredAt };
  const measurementRows = row.measurements && Object.keys(row.measurements).length ? `<h2>Measured results</h2>${row.measurementConditions ? `<p><strong>Measurement conditions:</strong> ${escape(row.measurementConditions)}</p>` : ''}<dl class="measurement-list">${Object.entries(row.measurements).map(([name, value]) => `<dt>${escape(name.replace(/([A-Z])/g, ' $1'))}</dt><dd>${escape(typeof value === 'boolean' ? (value ? 'Yes' : 'No') : String(value))}</dd>`).join('')}</dl>` : '';
  const field = (heading, value) => value ? `<h2>${heading}</h2><p>${escape(value)}</p>` : '';
  const relationships = (row.relatedExperimentIds || []).map(id => snapshot.experiments.find(item => item.id === id)).filter(Boolean);
  const relations = relationships.length ? `<h2>Related experiments</h2><ul>${relationships.map(item => `<li><a href="/live/experiments/${encodeURIComponent(item.id)}/">${escape(item.title)}</a></li>`).join('')}</ul>` : '';
  const component = row.architectureComponent ? `<p class="source-note">Architecture component: <a href="/how-it-works/#${encodeURIComponent(row.architectureComponent)}">${escape(row.architectureComponent)} →</a></p>` : '';
  const detail = page(escape(row.title), `Experiment · ${escape(row.status)} · ${escape(row.lifecycleStatus || 'lifecycle unknown')}`, `<p class="lede narrow">${escape(row.summary)}</p><section class="doc-content">${field('Research question',row.researchQuestion)}${field('Why this matters',row.whyItMatters)}${field('What was tested',row.candidateMethod)}${field('Baseline',row.baseline)}${field('Comparison conditions',row.comparisonConditions)}${field('Test environment',row.environment)}${field('Observed result',row.result)}${field('Outcome',row.outcome)}${measurementRows}${field('Evaluation method',row.evaluationMethod)}${field('External model usage',row.externalModelUsage)}${field('Cold reload',row.coldReloadResult)}${field('Causal ablation',row.causalAblationResult)}${field('Transfer',row.transferResult)}<h2>Verification and lifecycle</h2><p>${escape(row.verificationStatus)} · ${escape(row.lifecycleStatus || 'lifecycle unknown')} · Measured ${escape(row.measuredAt)} · Report ${escape(row.reportVersion)}</p>${field('Limitations',row.limitations || 'Limitations were not included in this approved record.')}${component}${relations}${field('Public provenance',row.publicProvenance)}<p class="fine-print">Source ${escape(row.sourceRecordId)} · Published ${escape(row.publishedAt)}</p><a class="text-link" href="/live/experiments/">Back to experiments <span aria-hidden="true">→</span></a></section>${commentsSection(route)}`);
  const dir = path.join(out, 'live', 'experiments', row.id);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(path.join(dir, 'index.html'), await shell(route, detail), 'utf8');
  try { await fs.access(path.join(root, 'assets/social-cards', `experiment-${row.id}.png`)); }
  catch { throw new Error(`Approved experiment ${row.id} is missing its unique social card. Run npm run social:cards before building.`); }
}
// Legacy locations remain reachable through noindex redirects; only canonical destinations enter metadata and the sitemap.
const aliases = [['/experiments/', '/live/experiments/'], ['/capabilities/', '/live/capabilities/'], ['/development/', '/live/timeline/'], ...snapshot.experiments.map(row => [`/experiments/${row.id}/`, `/live/experiments/${row.id}/`])];
for (const [oldRoute, newRoute] of aliases) {
  const dir = path.join(out, oldRoute.replace(/^\//, '').replace(/\/$/, ''));
  await fs.mkdir(dir, { recursive: true });
  const destination = `${config.domain}${newRoute}`;
  await fs.writeFile(path.join(dir, 'index.html'), `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><link rel="canonical" href="${destination}"><meta http-equiv="refresh" content="0;url=${newRoute}"><title>Page moved: ${newRoute} | LARI</title></head><body><main><h1>This page has moved</h1><p><a href="${newRoute}">Continue to ${newRoute}</a></p></main><script>location.replace(${JSON.stringify(newRoute)})</script></body></html>`, 'utf8');
}
await fs.cp(path.join(root, 'assets'), path.join(out, 'assets'), { recursive: true });
await fs.cp(path.join(root, 'data/approved'), path.join(out, 'data'), { recursive: true });
const publicManifest = { schemaVersion: 1, snapshotId: snapshot.snapshotId, status: snapshot.status, publishedAt: snapshot.publishedAt, generatedAt: snapshot.generatedAt, contentDigest: snapshot.contentDigest, snapshotUrl: '/data/approved/snapshot.json', recordCounts: { experiments: snapshot.experiments.length, capabilities: snapshot.capabilities.length, milestones: snapshot.milestones.length, metrics: snapshot.metrics.length } };
await fs.writeFile(path.join(out, 'data/manifest.json'), `${JSON.stringify(publicManifest, null, 2)}\n`, 'utf8');
await fs.copyFile(path.join(root, 'robots.txt'), path.join(out, 'robots.txt'));
await fs.copyFile(path.join(root, 'CNAME'), path.join(out, 'CNAME'));
await fs.copyFile(path.join(root, 'google4aaa287e48ffc299.html'), path.join(out, 'google4aaa287e48ffc299.html'));
const sitemap = Object.entries(meta).map(([route, info]) => {
  const baseDate = info.lastModified || config.contentUpdatedAt || snapshot.generatedAt;
  const snapshotDate = route === '/live/' && snapshot.generatedAt ? snapshot.generatedAt : null;
  const value = snapshotDate && Date.parse(snapshotDate) > Date.parse(baseDate) ? snapshotDate : baseDate;
  const lastmod = value ? `<lastmod>${escape(new Date(value).toISOString().slice(0, 10))}</lastmod>` : '';
  return `<url><loc>${config.domain}${route}</loc>${lastmod}</url>`;
}).join('');
await fs.writeFile(path.join(out, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemap}</urlset>`, 'utf8');
process.stdout.write(`Built ${Object.keys(content).length} static routes in dist/\n`);
